import sys

MOD = 998244353


class ParityDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.xr = [0] * n  # xor from node to its parent
        self.components = n

    def find(self, x):
        nodes = []
        y = x
        dist = 0
        while self.parent[y] != y:
            nodes.append(y)
            dist ^= self.xr[y]
            y = self.parent[y]

        root = y
        acc = 0
        for v in reversed(nodes):
            acc ^= self.xr[v]
            self.parent[v] = root
            self.xr[v] = acc
        return root, dist

    def union(self, a, b, w):
        ra, da = self.find(a)
        rb, db = self.find(b)

        if ra == rb:
            return (da ^ db) == w

        # Required xor between the two roots.
        rel = da ^ db ^ w

        if self.size[ra] < self.size[rb]:
            self.parent[ra] = rb
            self.xr[ra] = rel
            self.size[rb] += self.size[ra]
        else:
            self.parent[rb] = ra
            self.xr[rb] = rel
            self.size[ra] += self.size[rb]

        self.components -= 1
        return True


def solve_case(h, w, grid):
    col_parity = [0] * w

    for row in grid:
        row_parity = 0
        for j, ch in enumerate(row):
            if ch == 65:  # ord('A')
                row_parity ^= 1
                col_parity[j] ^= 1
        if row_parity:
            return 0

    if any(col_parity):
        return 0

    dsu = ParityDSU(h + w)
    col_prefix = [0] * w

    for i, row in enumerate(grid):
        row_prefix = 0

        for j, ch in enumerate(row):
            if ch == 66:  # ord('B')
                # R_i xor C_j = 1 xor (#A before j in row i)
                #                   xor (#A before i in column j)
                relation = 1 ^ row_prefix ^ col_prefix[j]
                if not dsu.union(i, h + j, relation):
                    return 0

            if ch == 65:
                row_prefix ^= 1

        for j, ch in enumerate(row):
            if ch == 65:
                col_prefix[j] ^= 1

    return pow(2, dsu.components, MOD)


def main():
    input = sys.stdin.buffer.readline
    t = int(input())
    answers = []

    for _ in range(t):
        h, w = map(int, input().split())
        grid = [input().strip() for _ in range(h)]
        answers.append(str(solve_case(h, w, grid)))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    main()

import sys

MOD = 998244353
PRIMITIVE_ROOT = 3


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(PRIMITIVE_ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []

    result_len = len(a) + len(b) - 1

    if min(len(a), len(b)) <= 32:
        result = [0] * result_len
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    result[i + j] = (result[i + j] + x * y) % MOD
        return result

    size = 1
    while size < result_len:
        size <<= 1

    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))

    ntt(fa, False)
    ntt(fb, False)

    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD

    ntt(fa, True)
    return fa[:result_len]


def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()

    if s[0] == "W":
        print(0)
        return

    length = 2 * n

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    black_positions = []
    white_prefix = [0] * (length + 1)
    white_count = 0

    for pos, ch in enumerate(s, 1):
        if ch == "W":
            white_count += 1
        else:
            black_positions.append(pos)
        white_prefix[pos] = white_count

    # Event j: immediately before the (j+1)-th black vertex,
    # all of the first j black vertices are matched to white vertices
    # lying to its left.
    #
    # q[j] is the number of white vertices before the (j+1)-th black.
    # The event is possible iff q[j] >= j.
    q = [-1] * (n + 1)
    for j in range(1, n):
        next_black_position = black_positions[j]
        whites_before_next_black = white_prefix[next_black_position - 1]
        if whites_before_next_black >= j:
            q[j] = whites_before_next_black

    # F[j] is the total signed inclusion-exclusion contribution
    # of subsets whose largest event index is j.
    #
    # F[j] = -(j-event singleton + contributions from earlier events)
    #        = -(fact[q[j]] + sum_{p<j} F[p] fact[q[j]-p])
    #           / (q[j]-j)!.
    F = [0] * (n + 1)
    accumulated = [0] * (n + 1)

    for j in range(1, n):
        if q[j] != -1:
            accumulated[j] = fact[q[j]]

    sys.setrecursionlimit(1_000_000)

    def cdq(left, right):
        if left == right:
            if q[left] != -1:
                F[left] = (
                    -accumulated[left] * invfact[q[left] - left]
                ) % MOD
            return

        mid = (left + right) >> 1

        cdq(left, mid)

        maximum_kernel_index = -1
        for j in range(mid + 1, right + 1):
            if q[j] != -1:
                maximum_kernel_index = max(
                    maximum_kernel_index,
                    q[j] - left
                )

        if maximum_kernel_index >= 0:
            left_values = F[left:mid + 1]
            kernel = fact[:maximum_kernel_index + 1]
            conv = convolution(left_values, kernel)

            for j in range(mid + 1, right + 1):
                if q[j] != -1:
                    index = q[j] - left
                    if index < len(conv):
                        accumulated[j] = (
                            accumulated[j] + conv[index]
                        ) % MOD

        cdq(mid + 1, right)

    if n > 1:
        cdq(1, n - 1)

    answer = fact[n]
    for j in range(1, n):
        answer = (answer + F[j] * fact[n - j]) % MOD

    print(answer)


if __name__ == "__main__":
    solve()

import sys
from array import array


class DominanceStructure:
    """Dynamic points (key, value), supporting:
       insert(key, value, index)
       max index among inserted points with key in [ql, qr] and value < threshold
    """
    __slots__ = ("size", "nodes", "bits")

    def __init__(self, points, n):
        size = 1
        while size <= n:
            size <<= 1
        self.size = size

        nodes = {}
        for key, value in points:
            p = size + key - 1
            while p:
                nodes.setdefault(p, []).append(value)
                p >>= 1

        for p, vals in nodes.items():
            vals = sorted(set(vals))
            nodes[p] = vals

        bits = {}
        for p, vals in nodes.items():
            bits[p] = array("i", [0]) * (len(vals) + 1)

        self.nodes = nodes
        self.bits = bits

    def update(self, key, value, idx):
        p = self.size + key - 1
        nodes = self.nodes
        bits = self.bits
        while p:
            vals = nodes.get(p)
            if vals is not None:
                lo, hi = 0, len(vals)
                while lo < hi:
                    mid = (lo + hi) >> 1
                    if vals[mid] < value:
                        lo = mid + 1
                    else:
                        hi = mid
                k = lo + 1
                bit = bits[p]
                while k < len(bit):
                    if bit[k] < idx:
                        bit[k] = idx
                    k += k & -k
            p >>= 1

    def _prefix(self, p, threshold):
        vals = self.nodes[p]
        lo, hi = 0, len(vals)
        while lo < hi:
            mid = (lo + hi) >> 1
            if vals[mid] < threshold:
                lo = mid + 1
            else:
                hi = mid
        k = lo
        bit = self.bits[p]
        ans = 0
        while k:
            if ans < bit[k]:
                ans = bit[k]
            k -= k & -k
        return ans

    def query(self, left, right, threshold):
        if left > right:
            return 0
        left += self.size - 1
        right += self.size - 1
        ans = 0
        while left <= right:
            if left & 1:
                if left in self.nodes:
                    v = self._prefix(left, threshold)
                    if ans < v:
                        ans = v
                left += 1
            if not (right & 1):
                if right in self.nodes:
                    v = self._prefix(right, threshold)
                    if ans < v:
                        ans = v
                right -= 1
            left >>= 1
            right >>= 1
        return ans


def main():
    input = sys.stdin.buffer.readline
    n, m, q = map(int, input().split())

    people = []
    plus_points_end = []
    minus_points_end = []
    plus_points_start = []
    minus_points_start = []

    for _ in range(m):
        s, t = map(int, input().split())
        if s < t:
            l, r, sign = s, t, 0
        else:
            l, r, sign = t, s, 1
        people.append((l, r, sign))
        if sign == 0:
            plus_points_end.append((r, l))
            plus_points_start.append((l, r))
        else:
            minus_points_end.append((r, l))
            minus_points_start.append((l, r))

    # For a crossing [a,b], [l,r] with a < l < b < r:
    # query by end b in (l,r), requiring start a < l.
    ds_pe = DominanceStructure(plus_points_end, n)
    ds_me = DominanceStructure(minus_points_end, n)

    # For a crossing [l,a], [r,b] with l < a < r < b:
    # query by start a in (l,r), requiring end b > r.
    # Convert "end > r" into value < threshold by storing -end.
    plus_points_start2 = [(k, n - v + 1) for k, v in plus_points_start]
    minus_points_start2 = [(k, n - v + 1) for k, v in minus_points_start]
    ds_ps = DominanceStructure(plus_points_start2, n)
    ds_ms = DominanceStructure(minus_points_start2, n)

    max_left_plus = [0] * (n + 1)
    max_left_minus = [0] * (n + 1)
    max_right_plus = [0] * (n + 1)
    max_right_minus = [0] * (n + 1)
    last_pair = {}

    bad = [0] * (m + 1)

    for i, (l, r, sign) in enumerate(people, 1):
        if sign == 0:
            d_end = ds_pe
            d_start = ds_ps
            ml = max_left_plus
            mr = max_right_plus
        else:
            d_end = ds_me
            d_start = ds_ms
            ml = max_left_minus
            mr = max_right_minus

        best = 0

        # Same left endpoint or same right endpoint.
        if ml[l] > best:
            best = ml[l]
        if mr[r] > best:
            best = mr[r]

        # Crossing with prior interval starting earlier.
        v = d_end.query(l + 1, r - 1, l)
        if v > best:
            best = v

        # Crossing with prior interval starting inside current interval
        # and ending later.
        # Stored value is n-end+1; end > r iff value < n-r+1.
        v = d_start.query(l + 1, r - 1, n - r + 1)
        if v > best:
            best = v

        # Same geometric interval with opposite orientation.
        v = last_pair.get((l, r, 1 - sign), 0)
        if v > best:
            best = v

        bad[i] = best

        # Insert current person into structures.
        if sign == 0:
            ds_pe.update(r, l, i)
            ds_ps.update(l, n - r + 1, i)
            if i > max_left_plus[l]:
                max_left_plus[l] = i
            if i > max_right_plus[r]:
                max_right_plus[r] = i
        else:
            ds_me.update(r, l, i)
            ds_ms.update(l, n - r + 1, i)
            if i > max_left_minus[l]:
                max_left_minus[l] = i
            if i > max_right_minus[r]:
                max_right_minus[r] = i

        last_pair[(l, r, sign)] = i

    size = 1
    while size <= m:
        size <<= 1
    seg = [0] * (2 * size)
    for i in range(1, m + 1):
        seg[size + i - 1] = bad[i]
    for p in range(size - 1, 0, -1):
        seg[p] = max(seg[p << 1], seg[p << 1 | 1])

    def range_max(left, right):
        left += size - 1
        right += size - 1
        ans = 0
        while left <= right:
            if left & 1:
                ans = max(ans, seg[left])
                left += 1
            if not (right & 1):
                ans = max(ans, seg[right])
                right -= 1
            left >>= 1
            right >>= 1
        return ans

    out = []
    for _ in range(q):
        l, r = map(int, input().split())
        out.append("Yes\n" if range_max(l, r) < l else "No\n")
    sys.stdout.write("".join(out))


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_right
from math import isqrt


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:1 + q]

    limit = isqrt(max(queries))

    spf = [0] * (limit + 1)
    primes = []

    for x in range(2, limit + 1):
        if spf[x] == 0:
            spf[x] = x
            primes.append(x)

        for p in primes:
            if p > spf[x] or p * x > limit:
                break
            spf[p * x] = p

    valid_squares = []

    for x in range(2, limit + 1):
        value = x
        distinct = 0

        while value > 1:
            p = spf[value]
            distinct += 1
            while value % p == 0:
                value //= p

            if distinct > 2:
                break

        if distinct == 2:
            valid_squares.append(x * x)

    output = []
    for a in queries:
        output.append(str(valid_squares[bisect_right(valid_squares, a) - 1]))

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

import sys
from collections import deque

LIMIT = 10**9
BASE = 500_000_000


def validate(ans, red_count, blue_count):
    n = red_count + blue_count
    if ans is None or len(ans) != n:
        return False

    seen = set()
    cr = cb = 0

    for i, (color, r, c) in enumerate(ans):
        if not (1 <= r <= LIMIT and 1 <= c <= LIMIT):
            return False
        if (r, c) in seen:
            return False
        seen.add((r, c))

        nr, nc = ans[(i + 1) % n][1], ans[(i + 1) % n][2]
        dr = abs(r - nr)
        dc = abs(c - nc)

        if color == "R":
            cr += 1
            if dr + dc != 1:
                return False
        elif color == "B":
            cb += 1
            if dr != 1 or dc != 1:
                return False
        else:
            return False

    return cr == red_count and cb == blue_count


def make_pure_red(n):
    if n == 2:
        return [
            ("R", BASE, BASE),
            ("R", BASE, BASE + 1),
        ]

    a = 1
    b = n // 2 - 1
    x = BASE
    y = BASE
    ans = []

    for i in range(a):
        ans.append(("R", x + i, y))
    for i in range(b):
        ans.append(("R", x + a, y + i))
    for i in range(a):
        ans.append(("R", x + a - i, y + b))
    for i in range(b):
        ans.append(("R", x, y + b - i))

    return ans


def make_pure_blue(n):
    if n == 2:
        return [
            ("B", BASE, BASE),
            ("B", BASE + 1, BASE + 1),
        ]

    a = 1
    b = n // 2 - 1
    u = 2 * BASE
    v = 0
    points = []

    for _ in range(a):
        points.append((u, v))
        u += 2
    for _ in range(b):
        points.append((u, v))
        v += 2
    for _ in range(a):
        points.append((u, v))
        u -= 2
    for _ in range(b):
        points.append((u, v))
        v -= 2

    return [
        ("B", (u0 + v0) // 2, (u0 - v0) // 2)
        for u0, v0 in points
    ]


def make_mixed(red_count, blue_count):
    nodes = []

    def add_node(r, c, color):
        idx = len(nodes)
        nodes.append([r, c, -1, color])
        return idx

    if blue_count & 1:
        base_coords = [(0, 0), (1, 0), (1, 1)]
        base_colors = ["R", "R", "B"]
    else:
        base_coords = [(0, 0), (1, 0), (2, 1), (1, 1)]
        base_colors = ["R", "B", "R", "B"]

    base_ids = []
    for (r, c), color in zip(base_coords, base_colors):
        base_ids.append(add_node(BASE + r, BASE + c, color))

    for i, idx in enumerate(base_ids):
        nodes[idx][2] = base_ids[(i + 1) % len(base_ids)]

    occupied = {(nodes[i][0], nodes[i][1]) for i in base_ids}
    queues = {"R": deque(), "B": deque()}

    for idx in base_ids:
        queues[nodes[idx][3]].append(idx)

    def expand(idx):
        color = nodes[idx][3]
        nxt = nodes[idx][2]
        r1, c1 = nodes[idx][0], nodes[idx][1]
        r2, c2 = nodes[nxt][0], nodes[nxt][1]

        candidates = []

        if color == "R":
            if r1 == r2:
                for shift in (-1, 1):
                    candidates.append(
                        ((r1 + shift, c1), (r2 + shift, c2))
                    )
            else:
                for shift in (-1, 1):
                    candidates.append(
                        ((r1, c1 + shift), (r2, c2 + shift))
                    )
        else:
            dr = r2 - r1
            dc = c2 - c1
            for sign in (1, -1):
                off_r = sign * dr
                off_c = -sign * dc
                candidates.append(
                    ((r1 + off_r, c1 + off_c),
                     (r2 + off_r, c2 + off_c))
                )

        for (wr, wc), (zr, zc) in candidates:
            if not (1 <= wr <= LIMIT and 1 <= wc <= LIMIT):
                continue
            if not (1 <= zr <= LIMIT and 1 <= zc <= LIMIT):
                continue
            if (wr, wc) in occupied or (zr, zc) in occupied:
                continue

            w = add_node(wr, wc, color)
            z = add_node(zr, zc, color)

            nodes[idx][2] = w
            nodes[w][2] = z
            nodes[z][2] = nxt

            occupied.add((wr, wc))
            occupied.add((zr, zc))
            queues[color].append(w)
            queues[color].append(z)
            return True

        return False

    def add_edges(color, amount):
        q = queues[color]
        for _ in range(amount):
            while q:
                idx = q.popleft()
                if expand(idx):
                    break
            else:
                return False
        return True

    base_blue = 1 if (blue_count & 1) else 2

    if not add_edges("R", (red_count - 2) // 2):
        return None
    if not add_edges("B", (blue_count - base_blue) // 2):
        return None

    ans = []
    cur = base_ids[0]
    for _ in range(red_count + blue_count):
        r, c, nxt, color = nodes[cur]
        ans.append((color, r, c))
        cur = nxt

    if cur != base_ids[0]:
        return None
    return ans


def solve_case(red_count, blue_count):
    if red_count & 1:
        return None

    if red_count == 0:
        if blue_count >= 2 and blue_count % 2 == 0:
            return make_pure_blue(blue_count)
        return None

    if blue_count == 0:
        if red_count >= 2:
            return make_pure_red(red_count)
        return None

    if red_count < 2:
        return None

    return make_mixed(red_count, blue_count)


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    pos = 1
    output = []

    for _ in range(t):
        red_count = data[pos]
        blue_count = data[pos + 1]
        pos += 2

        ans = solve_case(red_count, blue_count)

        if not validate(ans, red_count, blue_count):
            output.append("No")
        else:
            output.append("Yes")
            output.extend(
                f"{color} {r} {c}"
                for color, r, c in ans
            )

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(n: int) -> int:
            """Return sum of floor(log_4(x)) + 1 for 1 <= x <= n."""
            if n <= 0:
                return 0

            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0
        for left, right in queries:
            required = prefix(right) - prefix(left - 1)
            answer += (required + 1) // 2

        return answer

from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(x: int) -> int:
            if x <= 0:
                return 0

            digits = tuple(int(c) for c in str(x))
            n = len(digits)
            total = 0

            for target_sum in range(1, 9 * n + 1):
                @lru_cache(maxsize=None)
                def dfs(
                    pos: int,
                    digit_sum: int,
                    product_mod: int,
                    started: bool,
                    has_zero: bool,
                    tight: bool,
                ) -> int:
                    if digit_sum > target_sum:
                        return 0
                    if digit_sum + 9 * (n - pos) < target_sum:
                        return 0

                    if pos == n:
                        if digit_sum != target_sum:
                            return 0
                        return int(started and (has_zero or product_mod == 0))

                    limit = digits[pos] if tight else 9
                    result = 0

                    for d in range(limit + 1):
                        next_tight = tight and (d == digits[pos])

                        if not started:
                            if d == 0:
                                # Still leading zeroes: they do not affect
                                # either the digit sum or digit product.
                                result += dfs(
                                    pos + 1,
                                    0,
                                    1 % target_sum,
                                    False,
                                    False,
                                    next_tight,
                                )
                            else:
                                result += dfs(
                                    pos + 1,
                                    d,
                                    d % target_sum,
                                    True,
                                    False,
                                    next_tight,
                                )
                        elif has_zero:
                            # Once an actual zero occurs, the product is zero
                            # forever, so only the sum remains relevant.
                            result += dfs(
                                pos + 1,
                                digit_sum + d,
                                0,
                                True,
                                True,
                                next_tight,
                            )
                        elif d == 0:
                            result += dfs(
                                pos + 1,
                                digit_sum,
                                0,
                                True,
                                True,
                                next_tight,
                            )
                        else:
                            result += dfs(
                                pos + 1,
                                digit_sum + d,
                                (product_mod * d) % target_sum,
                                True,
                                False,
                                next_tight,
                            )

                    return result

                total += dfs(0, 0, 1 % target_sum, False, False, True)

            return total

        return count_up_to(r) - count_up_to(l - 1)

