class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        # Clockwise perimeter coordinate, with each corner assigned once.
        for x, y in points:
            if y == 0:
                pos = x
            elif x == side:
                pos = side + y
            elif y == side:
                pos = 3 * side - x
            else:
                pos = perimeter - y
            positions.append(pos)

        positions.sort()
        n = len(positions)

        def feasible(distance: int) -> bool:
            if distance == 0:
                return True

            if k * distance > perimeter:
                return False

            doubled = positions + [p + perimeter for p in positions]
            m = 2 * n

            # next_index[i] is the first index j with
            # doubled[j] - doubled[i] >= distance.
            next_index = [m] * m
            j = 0

            for i in range(m):
                if j < i + 1:
                    j = i + 1
                target = doubled[i] + distance
                while j < m and doubled[j] < target:
                    j += 1
                next_index[i] = j

            # Fix each possible first point and greedily take the earliest
            # possible next point.
            for start in range(n):
                current = start

                for _ in range(k - 1):
                    current = next_index[current]
                    if current >= start + n:
                        break
                else:
                    closing_gap = doubled[start] + perimeter - doubled[current]
                    if closing_gap >= distance:
                        return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

from bisect import bisect_left


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split("*")

        def find_occurrences(pattern: str):
            if not pattern:
                return None

            m = len(pattern)
            prefix = [0] * m
            j = 0

            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            occurrences = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1

                if j == m:
                    occurrences.append(i - m + 1)
                    j = prefix[j - 1]

            return occurrences

        occ_a = find_occurrences(a)
        occ_b = find_occurrences(b)
        occ_c = find_occurrences(c)

        if occ_a is None:
            first_positions = range(n + 1)
        else:
            first_positions = occ_a

        answer = n + 1

        for start_a in first_positions:
            end_a = start_a + len(a)

            if occ_b is None:
                start_b = end_a
            else:
                index_b = bisect_left(occ_b, end_a)
                if index_b == len(occ_b):
                    continue
                start_b = occ_b[index_b]

            end_b = start_b + len(b)

            if occ_c is None:
                start_c = end_b
            else:
                index_c = bisect_left(occ_c, end_b)
                if index_c == len(occ_c):
                    continue
                start_c = occ_c[index_c]

            answer = min(answer, start_c + len(c) - start_a)

        return -1 if answer == n + 1 else answer

