        root = pow(PRIMITIVE_ROOT, (MOD - 1) // length, MOD)
        if invert:
            root = pow(root, MOD - 2, MOD)

        roots = [1] * half
        for i in range(1, half):
            roots[i] = roots[i - 1] * root % MOD

        for start in range(0, n, length):
            end = start + half
            for j in range(half):
                u = a[start + j]
                v = a[end + j] * roots[j] % MOD

                x = u + v
                if x >= MOD:
                    x -= MOD

                y = u - v
                if y < 0:
                    y += MOD

                a[start + j] = x
                a[end + j] = y

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


