from typing import List


class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k - 1

        def bounded_pairs(a: int, b: int) -> int:
            # Count pairs (x, y) such that:
            # 0 <= x < a, 0 <= y < b, and x + y <= limit.
            def unrestricted(width: int, s: int) -> int:
                if s < 0:
                    return 0
                q = min(width, s + 1)
                return q * (s + 1) - q * (q - 1) // 2

            # Remove pairs with y >= b by shifting y down by b.
            return unrestricted(a, limit) - unrestricted(a, limit - b)

        def extremum_sum(find_max: bool) -> int:
            left = [0] * n
            right = [0] * n

            stack = []

            # Previous strictly greater element for maxima,
            # or previous strictly smaller element for minima.
            for i, value in enumerate(nums):
                if find_max:
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()

                left[i] = i - (stack[-1] if stack else -1)
                stack.append(i)

            stack = []

            # Next greater-or-equal element for maxima,
            # or next smaller-or-equal element for minima.
            for i in range(n - 1, -1, -1):
                value = nums[i]

                if find_max:
                    while stack and nums[stack[-1]] < value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > value:
                        stack.pop()

                right[i] = (stack[-1] if stack else n) - i
                stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                total += value * bounded_pairs(left[i], right[i])

            return total

        return extremum_sum(True) + extremum_sum(False)

from typing import List


class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]

        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        depth = [0] * n
        distance = [0] * n
        nearest_repeat = [-1] * n

        # Root the tree and determine the nearest equal-valued ancestor
        # for every node. Enter/exit events restore values on backtracking.
        last_depth = {}
        stack = [(0, -1, 0)]  # node, parent, event: 0 = enter, 1 = exit

        while stack:
            node, par, event = stack.pop()

            if event == 0:
                parent[node] = par

                if par != -1:
                    depth[node] = depth[par] + 1

                value = nums[node]
                previous_depth = last_depth.get(value, -1)
                nearest_repeat[node] = previous_depth
                last_depth[value] = depth[node]

                stack.append((node, previous_depth, 1))

                for neighbor, weight in graph[node]:
                    if neighbor == par:
                        continue
                    distance[neighbor] = distance[node] + weight
                    stack.append((neighbor, node, 0))
            else:
                value = nums[node]
                if par == -1:
                    del last_depth[value]
                else:
                    last_depth[value] = par

        # Traverse again while maintaining the current root-to-node path.
        # For each endpoint, compute the earliest valid starting depth.
        valid_start_bound = [-1] * n
        path = []

        best_length = -1
        min_nodes = n + 1

        stack = [(0, 0)]  # node, event: 0 = enter, 1 = exit

        while stack:
            node, event = stack.pop()

            if event == 0:
                path.append(node)

                if parent[node] == -1:
                    valid_start_bound[node] = nearest_repeat[node]
                else:
                    valid_start_bound[node] = max(
                        valid_start_bound[parent[node]],
                        nearest_repeat[node],
                    )

                start_depth = valid_start_bound[node] + 1
                start_node = path[start_depth]

                path_length = distance[node] - distance[start_node]
                node_count = depth[node] - start_depth + 1

                if path_length > best_length:
                    best_length = path_length
                    min_nodes = node_count
                elif path_length == best_length:
                    min_nodes = min(min_nodes, node_count)

                stack.append((node, 1))
                for neighbor, _ in graph[node]:
                    if neighbor != parent[node]:
                        stack.append((neighbor, 0))
            else:
                path.pop()

        return [best_length, min_nodes]

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total_cells = m * n

        fact = [1] * (total_cells + 1)
        for i in range(1, total_cells + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact_k2 = pow(fact[k - 2], MOD - 2, MOD)
        inv_fact_rest = pow(fact[total_cells - k], MOD - 2, MOD)
        arrangements_per_pair = (
            fact[total_cells - 2] * inv_fact_k2 % MOD * inv_fact_rest
        ) % MOD

        row_distance_sum = (
            n * n * m * (m - 1) * (m + 1) // 6
        )
        column_distance_sum = (
            m * m * n * (n - 1) * (n + 1) // 6
        )

        total_pair_distance = (row_distance_sum + column_distance_sum) % MOD
        return total_pair_distance * arrangements_per_pair % MOD

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    n = next(it)
    contests = [(next(it), next(it)) for _ in range(n)]
    q = next(it)
    queries = [next(it) for _ in range(q)]

    M = 500000
    size = 1
    while size < M:
        size <<= 1

    tree = [0] * (2 * size)
    lazy = [0] * (2 * size)

    tree[size:size + M] = range(1, M + 1)
    for i in range(size - 1, 0, -1):
        tree[i] = max(tree[i << 1], tree[i << 1 | 1])

    def push(node):
        value = lazy[node]
        if value:
            left = node << 1
            right = left | 1
            tree[left] += value
            lazy[left] += value
            tree[right] += value
            lazy[right] += value
            lazy[node] = 0

    def first_at_least(node, left, right, value):
        if tree[node] < value:
            return size + 1
        if left == right:
            return left

        push(node)
        mid = (left + right) >> 1
        child = node << 1
        if tree[child] >= value:
            return first_at_least(child, left, mid, value)
        return first_at_least(child | 1, mid + 1, right, value)

    def range_add(node, left, right, ql, qr):
        if ql <= left and right <= qr:
            tree[node] += 1
            lazy[node] += 1
            return

        push(node)
        mid = (left + right) >> 1
        child = node << 1

        if ql <= mid:
            range_add(child, left, mid, ql, qr)
        if mid < qr:
            range_add(child | 1, mid + 1, right, ql, qr)

        tree[node] = max(tree[child], tree[child | 1])

    for l, r in contests:
        start = first_at_least(1, 1, size, l)
        if start > M:
            continue

        end = first_at_least(1, 1, size, r + 1) - 1
        if end > M:
            end = M

        if start <= end:
            range_add(1, 1, size, start, end)

    answers = []
    for x in queries:
        node = 1
        add = 0
        left = 1
        right = size

        while left != right:
            add += lazy[node]
            mid = (left + right) >> 1
            if x <= mid:
                node <<= 1
                right = mid
            else:
                node = node << 1 | 1
                left = mid + 1

        answers.append(str(tree[node] + add))

    sys.stdout.write("\n".join(answers))


