from bisect import bisect_left
from typing import List


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        items = sorted(
            (right, left, weight, index)
            for index, (left, right, weight) in enumerate(intervals)
        )
        ends = [right for right, _, _, _ in items]
        n = len(items)

        # dp[i][k] = (best score, lexicographically smallest tuple)
        # using exactly k intervals among the first i sorted intervals.
        dp = [[(0, ())] + [(-1, ()) for _ in range(4)]]

        for i, (right, left, weight, index) in enumerate(items):
            current = dp[i].copy()

            # Only intervals ending strictly before left are compatible.
            predecessor_count = bisect_left(ends, left)
            predecessor = dp[predecessor_count]

            for count in range(1, 5):
                previous_score, previous_indices = predecessor[count - 1]
                if previous_score < 0:
                    continue

                position = bisect_left(previous_indices, index)
                candidate_indices = (
                    previous_indices[:position]
                    + (index,)
                    + previous_indices[position:]
                )
                candidate_score = previous_score + weight

                best_score, best_indices = current[count]
                if (
                    candidate_score > best_score
                    or (
                        candidate_score == best_score
                        and candidate_indices < best_indices
                    )
                ):
                    current[count] = (candidate_score, candidate_indices)

            dp.append(current)

        best_score, best_indices = dp[n][0]
        for count in range(1, 5):
            score, indices = dp[n][count]
            if score > best_score or (
                score == best_score and indices < best_indices
            ):
                best_score, best_indices = score, indices

        return list(best_indices)

from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        best_no_delete = nums[0]
        current = nums[0]
        for value in nums[1:]:
            current = max(value, current + value)
            best_no_delete = max(best_no_delete, current)

        values = list(dict.fromkeys(nums))
        m = len(values)

        # Deleting the only distinct value would empty the array.
        if m == 1:
            return best_no_delete

        index = {value: i for i, value in enumerate(values)}
        neg_inf = -(10**30)
        inf = 10**30

        min1 = [neg_inf] * (4 * m)
        min2 = [inf] * (4 * m)
        maximum = [neg_inf] * (4 * m)
        lazy_add = [0] * (4 * m)

        def pull(node: int) -> None:
            left = node * 2
            right = left + 1

            maximum[node] = max(maximum[left], maximum[right])

            if min1[left] < min1[right]:
                min1[node] = min1[left]
                min2[node] = min(min2[left], min1[right])
            elif min1[left] > min1[right]:
                min1[node] = min1[right]
                min2[node] = min(min1[left], min2[right])
            else:
                min1[node] = min1[left]
                min2[node] = min(min2[left], min2[right])

        def apply_add(node: int, value: int) -> None:
            min1[node] += value
            if min2[node] < inf:
                min2[node] += value
            maximum[node] += value
            lazy_add[node] += value

        def apply_chmax(node: int, value: int) -> None:
            if value <= min1[node]:
                return

            old_min = min1[node]
            min1[node] = value
            if maximum[node] == old_min:
                maximum[node] = value

        def push(node: int) -> None:
            left = node * 2
            right = left + 1

            if lazy_add[node]:
                value = lazy_add[node]
                apply_add(left, value)
                apply_add(right, value)
                lazy_add[node] = 0

            parent_min = min1[node]
            if min1[left] < parent_min:
                apply_chmax(left, parent_min)
            if min1[right] < parent_min:
                apply_chmax(right, parent_min)

        def range_chmax(node: int, left: int, right: int, value: int) -> None:
            if value <= min1[node]:
                return

            if value < min2[node]:
                apply_chmax(node, value)
                return

            push(node)
            mid = (left + right) // 2
            range_chmax(node * 2, left, mid, value)
            range_chmax(node * 2 + 1, mid + 1, right, value)
            pull(node)

        def point_query(
            node: int, left: int, right: int, position: int
        ) -> int:
            if left == right:
                return min1[node]

            push(node)
            mid = (left + right) // 2
            if position <= mid:
                return point_query(node * 2, left, mid, position)
            return point_query(node * 2 + 1, mid + 1, right, position)

        def point_set(
            node: int,
            left: int,
            right: int,
            position: int,
            value: int,
        ) -> None:
            if left == right:
                min1[node] = value
                min2[node] = inf
                maximum[node] = value
                lazy_add[node] = 0
                return

            push(node)
            mid = (left + right) // 2
            if position <= mid:
                point_set(node * 2, left, mid, position, value)
            else:
                point_set(node * 2 + 1, mid + 1, right, position, value)
            pull(node)

        for value in nums:
            position = index[value]

            # The current occurrence is deleted for this state.
            unchanged = point_query(1, 0, m - 1, position)

            # For all other states:
            # dp = max(previous_dp + value, value).
            apply_add(1, value)
            range_chmax(1, 0, m - 1, value)

            # Restore the exceptional state.
            point_set(1, 0, m - 1, position, unchanged)

        return max(best_no_delete, maximum[1])

import sys

MOD = 998244353

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = [x - 1 for x in map(int, input().split())]

    indeg = [0] * N
    for v in A:
        indeg[v] += 1

    queue = [i for i in range(N) if indeg[i] == 0]
    order = []

    for v in queue:
        order.append(v)
        to = A[v]
        indeg[to] -= 1
        if indeg[to] == 0:
            queue.append(to)

    is_cycle = [indeg[i] > 0 for i in range(N)]

    children = [[] for _ in range(N)]
    for v in range(N):
        if not is_cycle[v]:
            children[A[v]].append(v)

    dp = [None] * N

    # The peeling order goes from leaves toward the cycles,
    # so children are processed before their parents.
    for v in order:
        cur = [1] * (M + 1)
        first = True

        for u in children[v]:
            arr = dp[u]
            s = 0

            if first:
                for k in range(1, M + 1):
                    s += arr[k]
                    if s >= MOD:
                        s -= MOD
                    cur[k] = s
                first = False
            else:
                for k in range(1, M + 1):
                    s += arr[k]
                    if s >= MOD:
                        s -= MOD
                    cur[k] = cur[k] * s % MOD

        dp[v] = cur

    answer = 1
    seen = [False] * N

    for start in range(N):
        if not is_cycle[start] or seen[start]:
            continue

        cycle = []
        v = start
        while not seen[v]:
            seen[v] = True
            cycle.append(v)
            v = A[v]

        contribution = [1] * (M + 1)

        for v in cycle:
            for u in children[v]:
                arr = dp[u]
                s = 0
                for k in range(1, M + 1):
                    s += arr[k]
                    if s >= MOD:
                        s -= MOD
                    contribution[k] = contribution[k] * s % MOD

        component_answer = sum(contribution[1:]) % MOD
        answer = answer * component_answer % MOD

    print(answer)

if __name__ == "__main__":
    solve()

